/* Schiffe · Schiffsgärten – Einführung und Regeln (Ship-Gardens S. 3–15). Quelle q:"sg" (Bookviewer ws_z2). Braucht schiffe-sg-daten.js davor. */
window.WS_NACH = window.WS_NACH || {}; WS_NACH.schiffe = WS_NACH.schiffe || [];
(function(L){ var K = "Schiffsgärten", Q = "sg";
L.push({id:"sg-ernte-an-deck", k:K, t:"Fülle an Deck", p:3, q:Q, b:[
 {erz:"Man kann die Wildnis nicht zähmen.\nDas hatte man ihr beigebracht, seit sie denken konnte, einer der Grundsätze des Lebens auf den Wellen. Man konnte mit der verdanten Welt koexistieren, ihre Vorteile und Gelegenheiten nutzen. Man konnte sogar einige Elemente der wuchernden Wellen aus Ast und Blüte eine Zeit lang erobern oder sich zumindest einreden, man hätte sie erobert, bevor sie unweigerlich zurückgefordert wurden.\nDoch etwas so unleugbar Freies wahrhaft zu zähmen war ein Narrenwerk, eine unmögliche Aufgabe.\nUnd doch waren die Eisenkiefer-Oliven in ihrem Garten saftig und ließen sich direkt vom Strauch essen. Die Schlachtmelonen in ihrem Steinhügelgarten hatten nie Stacheln gebildet. Selbst die Samen in ihrer Hand, vor wenigen Augenblicken aus Wagon-Wyrs gezogen, lagen mit kaum einem Kribbeln Crezzerin auf ihrer Handfläche.\nEs ist also weithin bekannte Weisheit, dass man die Wildnis nie zähmen kann.\nDoch Weisheit ist, was man daraus macht."},
 {erz:"Die Welt von Kleine war in den Stunden fern vom Schiff geschrumpft. Die Weite der Wildnis zugleich zu nah und zu fern, jede Minute zwischen den Ästen eine aus Blut, Schweiß und Pollen.\nAber Kleine war aus einem Grund hier draußen, und Kleine war gut in dem, was getan werden musste. Mit jedem Hieb der Machete schnitt Kleine Brocken stacheliger Rinde von dem Nadelgranaten-Büschel, an das Kleine sich festgeschnallt hatte, hielt nur von Zeit zu Zeit inne, um die Umgebung zu prüfen und sich mit dem Rücken einer schwer behandschuhten Hand den Schweiß von der Stirn zu wischen.\nBlut, Schweiß und Pollen. Alle drei im Überfluss.\nAber auch Samen, die aus dem Kern der ruinierten Frucht in unten festgeseilte Gläser tropften. Sie würden Behandlung brauchen, De-Crezzung, doch …\nKleine strich ehrfürchtig über sie, bevor der Rucksack festgezurrt und die müden Glieder gestreckt wurden.\nNoch keine Rast, allerdings. Es gab zu pflanzen."},
 {a:"In den frühesten Tagen der Baumwipfel-Seefahrt füllten Crews ihre Frachträume mit in Häfen gezogenen Vorräten. Auf den Wellen gab es Früchte und Beeren, so weit das Auge reichte, doch die Wirkungen von Crezzerin waren ebenso entsetzlich wie schlecht verstanden – kein Wildsegler der ersten Generation hätte riskiert, von gepflücktem Gemüse und gestohlenen Pilzen zu überleben, wenn es sicherere, weniger mutative Mahlzeiten gab.\nDoch die Zeiten änderten sich zum Besseren. Bald war es üblich, als Teil einer Reise zu jagen und zu sammeln, eifrige Chars und Hafenschlachtereien lernten die wirksamsten Wege, Crezzerin, Milben, Sporen und eine ganze Reihe von auf den Wellen getragenen Giften zu entfernen oder zu bekämpfen. Kombüsen wurden nur noch mit dem Allernötigsten bestückt, und die meisten Crews verließen sich auf die Großzügigkeit des Gestrüpps, um die wenigen mitgebrachten Vorräte aufzustocken.\nSchiffsgärten waren der natürliche nächste Schritt – sie nahmen den Zufall aus der Gleichung und verringerten die Gefahr. Warum immer wieder über die Reling steigen, um eine Crew zu ernähren, wenn man es auch einmal tun, die Samen von allem, was man fand, behandeln und mehr davon in der Sicherheit des Schiffs anbauen konnte? Warum Steeps und Chars zwingen, sich mit crezzergetränkten Zutaten herumzuschlagen, wenn man (nach sorgfältigem Anbau und ein paar Zyklen aus Aussaat und Ernte) Nahrungsmittel mit wilder Vielfalt und Vor-V-Sicherheit erzeugen konnte?\nUnd mit der wachsenden Beliebtheit des Gärtnerns an Deck entwickelten sich auch die Technologien weiter, die es möglich machten. Von Tontöpfen bis zu Algenfarmen, von undichten Eimern bis zu motorbetriebenen Bewässerungssystemen, von staubartig gestohlenen Böden bis zu gedeihendem Tausendfüßlermulch und eigens gezüchteten Eisenschösslingen … So wie jeder Wildsegler auf seine Art einzigartig ist, ist jeder Schiffsgarten ein Ökosystem, einzigartig für das Deck (oder Kabinendach oder den geschleppten Kahn), auf dem er wächst."},
 {h:"Was anbauen?"},
 {a:"Ebenso wie Schiffsgärten für verschiedene Crews in ihrer Bauweise unterschiedliche Formen annehmen, werden die darin enthaltenen Pflanzen oft nach den Vorteilen gewählt, die sie bringen können. Denn welches Schiff und welchen Zweck die Crew auch hat, es gibt immer eine Gabe der Wildnis, die das Leben leichter machen könnte. Draußen auf See könnte eine Crew auf Folgendes stoßen …"},
 {l:["Der Longjaw eines Baggerers mit Töpfen voller Eisenkiefer-Oliven oder Jetlinge, die im Maschinenraum hängen, bereit, gepflückt und in den Motor geschoben zu werden, für einen Kraftschub beim Schleppen übergroßen Bergeguts.",
  "Langstrecken-Frachthändler, die Aestivians und Crewgurken im Raum hinter dem Bug anbauen, köstliche Grundlagen, aus denen ihre Chars Eintöpfe und Suppen machen, selbst beim Durchqueren karger Gegenden.",
  "Eine Jagdbark mit vor Anker liegender Crew, die Masten umkränzt von Hexnesseln (bereit, bei Ansitzen oder nächtlichen Verfolgungen gekaut zu werden, um die Crew wach und aufmerksam zu halten).",
  "Die Segler auf einem Winterschreiter, einem Schiff, das gebaut wurde, den Handel selbst in den bittersten Monaten aus sprödem Ast und gebrochenem Blatt am Laufen zu halten, die ihre Decks mit den Purpurtönen von Quava-Büschen teilen, köstlichen Beeren, die selbst im härtesten Schnee knospen.",
  "Das Vorderdeck eines Medizinschiffs, beherrscht von einem Weidenpede-Baum, behandschuhte Chirurgen, die die beunruhigend beweglichen Äste für Umschläge und Heilmittel ernten.",
  "Ein Luftschiff, das überfliegt, sein Bauch von seepockenartigen Wucherungen aus Abschaumkirschen und Blühendem Cactez vernarbt.",
  "Ein riesiges Ektus-Glasschiff, das unter dem Gewicht eines ganzen Hains aus Eisenschösslingen ächzt, jeder von ihnen Basis für Chomaten-Ranken und in wassergefüllten Bottichen voller Wildreis stehend.",
  "Ein Tauchboot, das nahe einem abgelegenen Hafen die Oberfläche des Gestrüpps durchbricht, die Türen des Kommandoturms vor Erleichterung nach so langer Zeit in den Tiefen der Wildnis aufgerissen, Tauchfahrer, die Kiste um Kiste Pilze hinaustragen, unter dem Jubel der Stauer und wartenden Händler."]}
]});

L.push({id:"sg-beginnen", k:K, t:"Einen Schiffsgarten beginnen", p:5, q:Q, b:[
 {a:"Es gibt drei wichtige Elemente in jedem Schiffsgarten, drei Dinge, die eine Crew für ihren Aufbruch in eine helle, landwirtschaftliche Zukunft braucht: Beete, Nährböden und Samen."},
 {c:"Beete", x:"Ein Bereich eines Schiffs, der speziell dem Anbau von Pflanzen gewidmet ist, wird Beet genannt. Das kann so schlicht sein wie ein Satz bemalter Bretter oder so komplex wie ein Bernsteinglas-Behälter zum Bündeln von Sonnenlicht."},
 {c:"Nährböden", x:"Hat eine Crew geklärt, wo auf dem Schiff der Anbau angemessen ist, braucht sie einen Nährboden, in dem diese Dinge wachsen. Pflanzen auf der Wildsea, selbst solche, die von den Eisenwurzeln und der ständigen Dosis Crezzerin aus den Wellen abgeschnitten sind, sind anpassungsfähig und schnellwachsend – eine riesige Vielfalt von Nährböden ist geeignet, doch manche sind wirksamer als andere."},
 {c:"Samen", x:"Das Paradox des Schiffsgartens ist, dass er, wenn man es genau nimmt, auf den Wellen beginnt. Hacker, Jäger und Agronauten durchkämmen das Gestrüpp nach gesunden Proben von Obst und Gemüse und spalten sie auf, um Samen für ihre Schiffe zu gewinnen."},
 {h:"Material beschaffen"},
 {a:"Die meisten Wildsegler-Crews sind durchaus fähig, aus allem Bergegut und allen Kuriositäten, die sie finden, nützliche Werkzeuge zusammenzuzimmern, doch sicheres und wirksames Gärtnern ist eine knifflige Kunst, die es zu meistern gilt. Gute Ausrüstung macht Gärten weit leichter zu bewirtschaften, und es gibt einige bestimmte Orte, die Crews aufsuchen können, um nützliche Ressourcen zu beschaffen."},
 {c:"Hafenwerkstätten", x:"So wie es Werkstätten gibt, die sich auf Waffen und Schiffsverteidigung spezialisieren, konzentrieren sich manche Einrichtungen auf die Entwicklung landwirtschaftlicher Werkzeuge, die den rauen Bedingungen eines Wildsegler-Schiffs standhalten."},
 {c:"Saatbanken", x:"Selten, aber äußerst nützlich: Dies sind Lager für Samen, die gezüchtet und vorbehandelt wurden, um verbliebenes Crezzerin zu entfernen."},
 {c:"Parasitenfarmen", x:"Die meisten Schiffsgärten schaffen es, genug Nahrung für ihre Crew zu erzeugen, mit vielleicht etwas Überschuss zum Handel in vorbeikommenden Häfen. Größere Siedlungen haben meist eigene Ackerflächen um sich herum, auf denen Parasitenpflanzen von den Ästen des Gestrüpps für verlässliche (wenn auch noch recht gefährliche) Ernten gezogen werden. Landwirtschaftliche Zentren wie diese haben meist Ausrüstung und Ressourcen, die man sie für die richtige Art Handelsware abzugeben überreden kann."}
]});

L.push({id:"sg-regeln", k:K, t:"Schiffsgarten-Regeln", p:6, q:Q, b:[
 {a:"Der Aufbau eines erfolgreichen Schiffsgartens mag in der tatsächlichen Welt der Wildsea schwierig sein, doch mechanisch braucht es nur einen zusätzlichen Bogen, ein paar weitere Leisten zum Markieren und einige einfache Regeln dazu, wie Wildsea-Pflanzen angebaut und geerntet werden können. Die nächsten Seiten behandeln …"},
 {l:["Gartenziele","Der Gartenbogen","Beete, Nährböden & Viertel","Samen & Aussaat","Wachstum & Ernte"]},
 {h:"Gartenziele"},
 {a:"Bevor du einen Schiffsgarten anlegst, ist es gut, zumindest eine grobe Vorstellung von deinen Zielen zu haben. Unten stehen einige der wichtigsten Gründe, aus denen eine Crew Pflanzen an Deck anbauen möchte, und was du beim Aufbau bedenken solltest …"},
 {c:"Für das Erlebnis", x:"Manchmal geht es nur darum, so viel wie möglich von dem zu erkunden, was die Welt zu bieten hat, oder die Regeln an ihre Grenzen zu treiben. Ist das der Fall, dann dreh auf – baue an, was du willst, in was du willst! Wenn es für dich cool klingt, tu es."},
 {c:"Fürs Überleben", x:"Eine riesige Vielfalt an Pflanzen kann genutzt werden, um das Überleben auf Reisen durch die Wildnis ein wenig leichter zu machen. Neben der Verwendung als Zutaten beim Kochen haben viele Pflanzen medizinische oder alchemistische Anwendungen, die sich durch sorgfältigen Anbau herausarbeiten oder verfeinern lassen."},
 {c:"Für den Handel", x:"Obwohl viele Schiffsgärten zur Versorgung der Crew dienen, existieren manche allein zum Handel. Die Ernten mögen lang und der Einstieg in Form von Einsätzen hoch sein, doch Crews, die handeln statt verbrauchen wollen, können reiche Belohnungen einfahren."},
 {c:"Für Handwerksressourcen", x:"Manchmal geht es nicht um Geschmack oder Wert, sondern um die Rohstoffe, die eine Pflanze liefern kann. Von Pilzstielen bis zu Bohnenschoten kann alles praktische Verwendungen für einen Baggerer oder Rattlehand mit einem Funken Kreativität haben."}
]});

L.push({id:"sg-gartenbogen", k:K, t:"Der Gartenbogen", p:7, q:Q, b:[
 {a:"Der Bogen ist ein einfacher – er hat Platz für Notizen und mehrere Felder für Beete. Jedes dieser Beete kann bis zu vier verschiedene Pflanzen enthalten und ist in Viertel unterteilt. Wir erläutern den Bogen hier im Ganzen und gehen in den nächsten Seiten auf die Einzelheiten ein."},
 {c:"1. Notizen", x:"Neben Platz, um beliebige nützliche Notizen aufzuschreiben, ist dieses Feld lang genug, um bequem Projektleisten aufzunehmen, die ins Spiel kommen können, wenn Crews ihre eigenen Schiffsgärten bauen wollen (mit Zeit, Schrott und Ressourcen statt gekauften Teilen)."},
 {c:"2. Nummerierte Beete", x:"Jeder Bogen hat Platz für vier Beete, die Bereiche, in denen du am Ende Pflanzen anbauen wirst. Zwar gibt es technisch keine Obergrenze für die Zahl der Beete auf einem Schiff, doch versuche, die erzählerische Lage dieser Beete auf deinem Schiff im Kopf zu behalten (sie kann bei Kämpfen und anderen dramatischen Ereignissen während einer Reise ins Spiel kommen)."},
 {c:"3. Beet-Typ und Nährboden", x:"Jedes der Beete, die du für den Gartenbau nutzt, hat einen Beet-Typ (der zeigt, was der Bereich physisch ist, etwa eine Ansammlung von Tontöpfen oder ein Blumenkasten) und einen Nährboden (der beschreibt, womit die Beete gefüllt sind, dem Material, das die Samen beim Wachsen nährt). Darunter gibt es außerdem Platz, um mechanische Boni oder Nachteile der Kombination aus Beet-Typ und Nährboden festzuhalten."},
 {c:"4. Viertel", x:"Jedes Beet hat vier Viertel, verschiedene Bereiche, die unterschiedliche Pflanzen- oder Samenarten aufnehmen können (diese Viertel sind von 1/4 bis 4/4 nummeriert). Das Wachstum in einem Schiffsgarten wird Pflanze für Pflanze verfolgt, daher hat jedes Viertel eine eigene Leiste, um verschiedene Wachstumsphasen zu markieren."}
]});

L.push({id:"sg-beete-naehrboeden-viertel", k:K, t:"Beete, Nährböden & Viertel", p:8, q:Q, b:[
 {a:"Obwohl die Informationen zum Schiffsgarten auf einem eigenen Bogen festgehalten werden, ist er (wenig überraschend) ein Teil deines Schiffs. Und wie jeder andere Teil deines Schiffs werden die Grundlagen eines Schiffsgartens – Beete und Nährböden – mit Einsätzen gekauft.\n… Oder gefunden. Oder selbst gebaut!\nWenn dein Schiffsgarten eingerichtet ist, wird das Wachstum in einem Beet Pflanze für Pflanze verfolgt, da manche mit sehr unterschiedlicher Geschwindigkeit wachsen oder auf unterschiedliche Bedingungen angewiesen sind. Säe Samen in einem Viertel (oder für manche Pflanzen in mehreren Vierteln gleichzeitig), pflege sie auf Reisen und gib ihnen etwas Zeit zum Wachsen, und du erhältst am Ende eine ausgewachsene, erntereife Pflanze."},
 {h:"Beete"},
 {a:"Ein Beet kann alles sein, von einem eingefassten Bett bis zu einem hängenden Topf, von einem Kreideumriss an Deck bis zu einer Dachparzelle. Die meisten Beete bringen einen Vorteil (oder Nachteil) mit sich, der jede Pflanze in ihren vier Vierteln betrifft."},
 {box:"Beispiel", x:["Die Crew der Curious Cat will sich im Gärtnern versuchen und hat ein paar Einsätze zum Ausgeben. Sie wissen, dass sie sowohl ein Beet als auch einen Nährboden brauchen, bevor sie Samen aussäen können, und wollen nicht gleich ins kalte Wasser springen – sie geben einen einzigen Einsatz aus, um einen Eifrigen Bienenstock aus einer Hafenwerkstatt zu holen, ein Beet, das die Wachstumsleisten aller darin wachsenden Pflanzen verringert, aber die Erntezeit schwieriger (und wahrscheinlich schmerzhafter) macht."]},
 {a:"Du kannst Beete auf verschiedene Arten erhalten …"},
 {l:["Mit Einsätzen kaufen in einer Hafenwerkstatt oder auf einer Parasitenfarm. Ein Beet auf diese Weise zu kaufen ist schnell und einfach, doch du wählst wahrscheinlich aus einer begrenzten Auswahl.",
  "Aus Wracks plündern, die du bei der Erkundung der Wellen findest. Auch das ist schnell und kostet nichts als Mühe, doch du bist der Ausstattung des Wracks ausgeliefert. Es kann auch Nachteile geben, etwa Schaden am Beet, der die Wirksamkeit verringert oder einige Viertel sperrt, bis es repariert ist.",
  "Aus den Ressourcen der Crew selbst zusammenbauen. Behandle dies als Projekt, mit drei Kästchen auf der Leiste für jeden Einsatz, den das Beet normalerweise kosten würde. Du kannst diese Projektleiste wie jede andere mit Ressourcen und guten Würfen füllen, und wenn ihr einen Rattlehand in der Crew habt, ist dies vielleicht der günstigste und wirksamste Einstieg."]},
 {h:"Nährböden"},
 {a:"Während das Beet alles enthält, was du anbauen willst, ist der Nährboden das, was es tatsächlich wachsen lässt – etwas voller Nährstoffe, ein Ort, an dem Pflanzen Wurzeln schlagen können. Manche Nährböden sind einfach und leicht zu finden, wie Mutamulch (eine Mischung aus Saft und Blättern, geladen mit Crezzerin und wohl mühelos aus dem Kielwasser eines Schiffs zu sammeln). Andere sind seltener und in Einsätzen teurer, wie Eisenschösslinge (Mini-Eisenwurzeln, auf denen andere Pflanzen wie Blätter wachsen können).\nDu kannst nur einen Nährboden pro Beet haben, und er füllt alle vier Viertel. Wie Beete bringen die meisten Nährböden einen Vorteil (oder Nachteil) mit sich, der jede darin wachsende Pflanze betrifft."},
 {box:"Beispiel", x:["Die Crew der Curious Cat hat ihr Beet installiert, und nun brauchen sie einen Nährboden, um es zu füllen. Sie beschließen, ihre Einsätze zu sparen und in die Wildnis zu ziehen, um etwas zu finden, und nach einiger Suche gelingt es ihnen, an etwas Monument-Erde zu kommen. Sie schaufeln sie in die Eifrigen Bienenstöcke, und dann sind sie bereit – die Erde wird jeder Hülsenfrucht und jedem Gemüse, die sie aussäen, schneller zum Wachsen verhelfen."]},
 {a:"Du kannst Nährböden auf verschiedene Arten erhalten …"},
 {l:["Mit Einsätzen kaufen in einer Saatbank oder auf einer Parasitenfarm. Einen Nährboden auf diese Weise zu kaufen ist schnell und einfach, doch du wählst wahrscheinlich aus einer begrenzten Auswahl.",
  "Aus den Wellen pflücken, die natürlichen Ressourcen der Wildnis nutzen, um dein Beet zu füllen. Das ist ebenfalls schnell und einfach, doch es gibt nur eine begrenzte Auswahl an Nährböden, die man den rauschenden Wellen entnehmen kann. Auf diese Weise erworbene Nährböden brauchen vielleicht Behandlung und Aufbereitung durch einen Thorn, Alchemisten oder Agronauten, bevor sie ihre volle Wirkung entfalten, was in Form eines Projekts mit einer 2er- oder 3er-Leiste geschehen kann."]}
]});

L.push({id:"sg-viertel", k:K, t:"Viertel", p:9, q:Q, b:[
 {a:"Unten siehst du die Aufschlüsselung eines einzelnen Viertels aus einem Beet des Gartenbogens, ausgefüllt für die Pflanze aus dem Beispiel rechts. Es enthält …"},
 {c:"1. Pflanzenname", x:"Ein Feld, in das du den Namen der Pflanze schreibst, die in diesem Viertel wächst. Nimmt eine Pflanze mehr als ein Viertel ein, kannst du alle Einzelheiten in eines eintragen und in die anderen Viertel, die die Pflanze belegt, „mehr _____“ schreiben (zum Beispiel „Mehr Eisenkiefer-Oliven“). Jeder Pflanzeneintrag in diesem Buch nennt direkt hinter seinem Namen die Zahl der Viertel, die er bei der Aussaat einnimmt. Du kannst den Namen einer Pflanze in dieses Feld schreiben, sobald der Samen gesät ist – so weißt du auch ohne markierte Kästchen (oder wenn die Kästchen der Wachstumsleiste der Pflanze geleert werden), was in jedem Viertel eines Beets ist."},
 {c:"2. Typ", x:"Ein Feld für den Typ der angebauten Pflanze (zum Beispiel Gemüse oder Kraut). Pflanzen haben standardmäßig einen Typ, doch es gibt die Möglichkeit der Kreuzung …"},
 {c:"3. Die Wachstumsleiste", x:"Dies ist eine besondere Art von Projektleiste, die gefüllt wird, wenn Zeit vergeht oder Pflanzen gepflegt werden. Die Länge einer Wachstumsleiste hängt hauptsächlich von der Pflanze ab, kann aber vom Beet-Typ und vom Nährboden beeinflusst werden (dazu gleich mehr). Ist eine Wachstumsleiste voll, ist eine Pflanze erntereif. In unserem Beispiel rechts ist das Ende der Leiste mit einem Verbrennen markiert."},
 {c:"4. Marker", x:"Erhält eine wachsende Pflanze einen Marker, ob positiv oder negativ, trage ihn in diesen Abschnitt ein; die fertig geernteten Pflanzen erhalten diese Marker dann ebenfalls. Zum Beispiel erhält eine wachsende Schlachtmelone nach ein paar Tagen in sengendem Sonnenlicht den Marker Verwelkt und dank der Zuwendung eines Agronauten den Marker Süß. Bei der Ernte ist die gewonnene Ressource eine Süße Verwelkte Schlachtmelone.\nEs gibt mehrere extrem häufige Marker, die in diesem Feld immer auftauchen, je nach Qualität der ausgesäten Samen (etwa Wild, Parasit und Erbstück). Die Bedeutung dieser wichtigen Marker wird auf den nächsten Seiten beschrieben."},
 {c:"5. Details", x:"Ein Feld für zusätzliche Einzelheiten, die während des Wachstums einer Pflanze von Belang sein könnten, aber keinen Marker ergeben. Das könnte eine Notiz für die Nachwelt sein, wie die Pflanze erworben wurde, eine Erinnerung daran, wofür sie nach dem Heranwachsen vorgesehen ist, oder ein Hinweis auf eine Gefahr, die beim Ernten oder Essen dessen liegt, was im Viertel wächst. Wenn du Schiffsgärten als Teil eines kulinarisch ausgerichteten Spiels nutzt, ist dies ein perfekter Ort, um feinere Einzelheiten zu Geschmack oder Zubereitung festzuhalten.\nDer Gartenbogen ist, genau wie der Schiffsbogen, eine gemeinsame Ressource – du kannst auch den Namen des Besitzers einer Pflanze festhalten, wenn mehrere grünfingrige Segler in einer Crew ihre Erzeugnisse eifersüchtig hüten."},
 {c:"6. Viertel-Markierung", x:"Eine bereits auf dem Bogen eingetragene Zahl, die zeigt, welches Viertel eines Beets das Kästchen darstellt. Das Kästchen oben links ist das erste Viertel, oben rechts das zweite, unten links (wie im Beispiel hier) das dritte und unten rechts das vierte Viertel. Mit Vierteln sind keine Vorteile verbunden, aber wird ein Beet beschädigt, können ein oder mehrere Viertel zerstört werden und die darin befindlichen Pflanzen verloren gehen."},
 {box:"Beispiel eines ausgefüllten Viertels", x:["Pflanze: Sägebananen · Viertel 3/4\nTyp: Frucht\nMarker: Erbstück, Geschärft\nDetails: Samen aus Kartzar Port, Bund an Ro Clara liefern"]},
 {bsp:"Beete & Nährböden im Spiel", z:[
  ["Vic","Das war's – sind wir bereit abzulegen?"],
  ["Inge","Wow, wow, wow, noch nicht ganz! Ich habe auf den Märkten hier einen Eisenschössling aufgetrieben, das ist ein Nährboden für Schiffsgärten. Und mit Tembas Bestienschädel, den er seit dem Wrack, das wir umgedreht haben, mit sich herumschleppt …"],
  ["Temba","Verdammt ja, das ist ein Beet! Zeit, die Finger grün zu machen, Leute!"],
  ["Glühwürmchen","Nun, mit Beet und Nährboden in der Hand könnt ihr irgendwo an Deck einen Garten anlegen. Ich weiß, das Schiff ist technisch ein Theater des Geistes, aber ihr habt es in den letzten paar Sitzungen ziemlich gut beschrieben … Wo kommt der Garten hin?"],
  ["Inge","Direkt hinter den Motor, denke ich, auf das Vorderdeck. Kann ich alles aufbauen, während wir ablegen?"],
  ["Glühwürmchen","Auf jeden Fall. Das ist ein Hohler Bestienschädel mit einem Eisenschössling darin, vier Viertel bereit zum Bepflanzen. Notiert das auf eurem Gartenbogen und haltet Ausschau nach Samen!"]
 ]}
]});

L.push({id:"sg-saatgut", k:K, t:"Samen & Aussaat", p:10, q:Q, b:[
 {erz:"Die Reise von Alfa nach Port CanBe-Seen war besonders zermürbend gewesen. Die Crew der Maxir war durch ein Feld aus Spalten gekrochen, hatte sich durch die klebrigen Fäden eines Tzelicrae-Plünderer-Netzfangs gekämpft und drei oder vier verschiedene Einfälle wildgewandelter Raubtiere abgewehrt (von denen die meisten gut genug für sie ausgegangen waren, wenn auch hart erkämpft). Es war nicht die Art von Reise, die sie gewöhnlich unternahmen, und da der Herbst mit Flügelschlägen durch die Wellen nahte, würden sie sie bald nicht wieder machen.\nDoch als das glitzernde Bernsteindach der Saatbank die untergehende Sonne einfing, war der Jubel der Crew alles, was der Kapitän der Maxir brauchte, um zu wissen, dass sie die richtige Entscheidung getroffen hatten."},
 {a:"Du hast also ein Beet angelegt und einen Nährboden, der es füllt. Vier offene Viertel, bereit für die Produktion. Doch … was willst du anbauen?\nNichts, ohne dass du Samen in die Hände bekommst.\nIn diesem Buch sind keine Samen aufgelistet, aber es gibt viele Pflanzen. Alle Pflanzen, die zwischen S. 20 und 30 aufgelistet sind, lassen sich im Spiel als Samen (oder, bei den Pilzen, als Sporen) erwerben. Vielleicht findest du nicht alle leicht, und sie stellen keineswegs alle Möglichkeiten dar, doch sie sind ein ausgezeichneter Anfang."},
 {h:"Samen finden"},
 {a:"Es gibt einige Wege, verlässlich an Samen zu kommen, manche leichter als andere. Du könntest …"},
 {l:["Sie in einer Saatbank kaufen: Für gewöhnliche Samen oder Samen mit negativen Markern ist das wahrscheinlich nur ein Tausch von Ressourcen. Für seltenere Samen oder Samen mit positiven Markern wirst du vielleicht gebeten, mehrere Ressourcen auf einmal oder sogar ein oder zwei Frachtstücke zu tauschen.",
  "Sie bei … weniger glücklichen Seglern finden: Ebenso wie Wracks eigene Beete zum Bergen enthalten können, findest du vielleicht Samen darin vergraben, in einer verschlossenen Kiste in der Nähe oder auf der Leiche eines Agronauten, Hackers oder Thorns.",
  "Sie von den Wellen selbst sammeln: Das ist ein verlässlicher Weg zu wilden Samen (mehr zu den verschiedenen Saatarten gleich), aber das Sammeln ist eine knifflige Sache. Immer wenn du eine Probe erntest (oder anderweitig erhältst), die keimfähige Samen enthalten könnte, wie eine Frucht oder ein Gemüse, kannst du die Probe stattdessen verbrauchen und erhältst dafür einen Satz Samen als Probe."]},
 {h:"Saatarten"},
 {a:"Wenn du Samen für die Pflanzen in diesem Abschnitt erhältst, tragen sie einen bestimmten Marker, je nach der Quelle, aus der sie stammen (ebenso wie daraus gewonnene Ressourcen). Wendungen bei Sammelwürfen können den Marker verbessern."},
 {c:"+ Wild", x:"Wilde Samen stammen aus Gebieten, die von Crezzerin durchdrungen sind (etwa den rauschenden Wellen selbst), und die Pflanzen, die sie hervorbringen, sind ähnlich chemisch verändert. Essbares, das von Wilden Pflanzen geerntet wird, verursacht beim Verzehr meist Gift-Schaden wegen des Crezzerin-Gehalts (sofern es nicht von einem erfahrenen Char oder Steep richtig zubereitet wurde)."},
 {c:"+ Wuchernd", x:"Diese Samen sind Echos der alten verdanten Explosion; die Pflanzen, die sie hervorbringen, triefen vor Chemikalien und sind eifrig darauf aus, sich auszubreiten. Pflanzen mit dem Marker Wuchernd nehmen beim Wachsen ein Viertel mehr als üblich ein, doch die Überladung mit Crezzerin ist durch Stängel und Blätter ausreichend eingedämmt, dass die hervorgebrachten Proben sicher zu essen sind. Würde der Marker Wuchernd die Zahl der benötigten Viertel auf fünf erhöhen, kann die Pflanze dennoch so ausgesät werden, als nähme sie vier Viertel ein, beschädigt aber beim Wachsen das Beet, was Reparaturen nötig macht."},
 {c:"+ Parasit", x:"Samen aus Parasitenfarmen, gezogen von Pflanzen, die sorgfältig an Eisenwurzelästen verankert wurden, mit einer viel geringeren Dosis Crezzerin. Pflanzen mit dem Marker Parasit haben ein zusätzliches Kästchen auf ihrer Wachstumsleiste, sind aber direkt nach der Ernte roh sicher zu essen."},
 {c:"+ Medizinisch", x:"Oft das Ergebnis alchemistischer Tüftelei, selten außerhalb von Laboren zu finden (obwohl manche Pflanzen unabhängig von ihrer Herkunft von Natur aus heilend sind). Pflanzen mit dem Marker Medizinisch haben zwei zusätzliche Kästchen auf ihrer Wachstumsleiste und leeren eine zusätzliche Markierung, wenn ihr Erzeugnis zur Heilung von Schaden an einer Aspektleiste oder einer Verletzung eingesetzt wird."},
 {c:"+ Erbstück", x:"Erbstück-Samen sind selten, entweder das Ergebnis jahrzehntelanger sorgfältiger Veredelung oder unverdorbener Vor-V-Saatbanken. Pflanzen mit dem Marker Erbstück haben drei zusätzliche Kästchen auf ihrer Wachstumsleiste, doch das entstehende Erzeugnis ist äußerst wertvoll."},
 {h:"Samen aussäen"},
 {a:"Hast du einen Satz Samen in der Hand, kannst du sie deinem Garten hinzufügen, indem du eine Aufgabe nutzt! Wenn du einen Samen hinzufügst, schau im entsprechenden Pflanzeneintrag zwischen S. 20 und 30 nach. Diese Einträge nennen dir die wichtigsten Informationen, nämlich die Zahl der Viertel, die der Samen zum Wachsen braucht, den Typ der Pflanze, die Länge der Wachstumsleiste und was du ernten kannst, wenn die Pflanze ausgewachsen ist.\nViertel und Typ behandeln wir unten, Wachstum und Ernte haben ihren eigenen Abschnitt auf der Seite rechts. Wir nutzen die hier abgebildete Schlachtmelone als durchgehendes Beispiel in diesem Abschnitt."},
 SG_P("slaughtermelons"),
 {c:"Anzahl benötigter Viertel", x:"Rechts vom Namen der Pflanze in kleinerer Schrift zu finden (ein Wert von 1/4 bis 4/4) – die linke Zahl sagt dir, wie viel eines Beets die Pflanze beim Wachsen einnimmt.\nIm Schlachtmelonen-Beispiel belegt das Aussäen von Schlachtmelonen-Samen drei Viertel eines Beets. Du kannst dem verbleibenden Platz weiterhin eine Pflanze hinzufügen, die nur 1/4 einnimmt, doch jene ersten 3/4 sind verbraucht, sobald die Samen gesät sind, noch bevor die Pflanze sichtbar zu wachsen begonnen hat."},
 {c:"Typ der Pflanze", x:"Typen (wie Hülsenfrucht oder Kraut) stehen rechts vom Namen einer Pflanze. Manche Pflanzen wachsen in bestimmten Nährböden besser als in anderen, und das liegt meist am Typ. Ein Gemüse in Monument-Erde zu säen erlaubt es dir zum Beispiel, das erste Kästchen seiner Wachstumsleiste sofort zu markieren.\nDie Schlachtmelone zählt als Frucht, daher markiert ihre Aussaat in Widerspenstiger Rinde die Wachstumsleiste der Pflanze früher."},
 {bsp:"Samen finden im Spiel", z:[
  ["Temba","Wenn ich je Parasitenfrucht reif zum Pflücken gesehen habe, dann diese Orange dort."],
  ["Glühwürmchen","Sieht tatsächlich ziemlich gut aus. Sie ist einen Steinwurf vom Schiff entfernt, wenn du da bleibst, wo du gerade bist. Wie sicher bist du als Wellenläufer, Temba? Kommst du mit einer Parasitenfarm klar?"],
  ["Vic","Oh, er ist nicht schlecht."],
  ["Temba","Verdammt richtig! Ich werfe mich über die Reling und lande laufend auf den Wellen, nutze Äste und Zweige, so gut ich kann, um mich zur Frucht durchzuschlagen, bevor diese Piraten uns einholen. Besser wir plündern als sie!"],
  ["Glühwürmchen","Kein Problem, würfle! Kein Abzug, du bist in deinem Element."],
  ["Temba","Das ist Anmut, zwei für Wellenlauf, und ich glaube, meine Stiefel helfen hier auch … 1, 2, 3 und 5. Das ist ein Konflikt!"],
  ["Glühwürmchen","Hätte definitiv schlimmer kommen können. Du gelangst ohne Probleme zur hängenden Frucht, doch dort angekommen, hast du ein Problem – die Ictorangen, an denen du dich hochziehst, sind dafür bekannt, nach der Reife rasch zu versauern, wenn du also eine gute Probe willst, musst du schnell sein."],
  ["Vic","Temba! Mach dir keine Gedanken um die Frucht, hol die Samen! Er würfelt dafür genauso, oder?"],
  ["Glühwürmchen","Richtig, nur die Probe, die du erhältst, ändert sich. Willst du die Samen, Temba?"],
  ["Temba","Scheint die sicherere Wette. Ich nehme Anmut, Bergen und meine Schere, um sie aufzubrechen … 1, 6 und 6! Ein Triumph mit Wendung! Kann ich den Marker verbessern?"],
  ["Glühwürmchen","Natürlich! Saure Säfte regnen herab, während du kurzen Prozess mit der Frucht machst. Füge Ictorangen-Samen als Probe hinzu, wobei der übliche Marker Parasit stattdessen durch den Marker Medizinisch ersetzt wird. Das sind verdammt gute Samen!"]
 ]},
 {bsp:"Aussäen im Spiel", z:[
  ["Vic","… Und das ist eine Sechs, Frieden. Ooh, können wir es als Montage nehmen, während wir reisen, und diese Ictorangen-Samen pflanzen? Wenn das für alle anderen passt, natürlich …"],
  ["Inge","Ich pflanze gern ein bisschen, klar!"],
  ["Temba","Ich habe Ausrüstung zu reparieren, das passt also für mich – kann ich ebenso gut hier draußen in der Sonne tun, um Inge Gesellschaft zu leisten."],
  ["Glühwürmchen","Keine Einwände, nutzt die Reise! Während das Schiff durch diesen friedlicheren Teil des Gestrüpps kriecht, gehen wir in eine Montage über. Temba, du kannst für diese Reparaturen würfeln, wenn du willst. Inge, es braucht eine Aufgabe, um die Samen zu pflanzen, wenn du magst. Vic?"],
  ["Vic","Ehrlich gesagt habe ich nicht weiter als bis zum Anlegen des Gartens gedacht. Kann ich ihnen, äh, beim Wachsen helfen oder so, sobald sie gepflanzt sind?"],
  ["Glühwürmchen","Auf jeden Fall, es ist deine Aufgabe. Inge, weißt du, wie das geht?"],
  ["Inge","Ziemlich sicher, ja. Ich nutze meine Aufgabe, um die Samen in kleine Vertiefungen und Knoten um die Äste des Eisenschösslings zu setzen, und ich notiere das auch auf dem Bogen. Ictorangen brauchen … zwei Viertel, und diese waren Medizinisch, richtig?"],
  ["Glühwürmchen","Richtig. Trag die Infos ins erste Viertel ein und schreib eine Notiz ins zweite: „mehr Ictorangen“. Wie lang ist die Leiste?"],
  ["Temba","Die kenne ich. Ictorangen wachsen ziemlich schnell, sie beginnen also als 2er-Leiste, aber der Marker Medizinisch fügt zwei weitere Kästchen hinzu. Also eine 4er-Leiste?"],
  ["Glühwürmchen","Richtig. Und mit den gepflanzten Samen musst du ihnen nur beim Wachsen zusehen! Oder ihnen ein wenig helfen, was mich zu dir bringt, Vic …?"]
 ]}
]});

L.push({id:"sg-wachstum-ernte", k:K, t:"Wachstum & Ernte", p:12, q:Q, b:[
 {a:"Ist ein Samen gesät, beginnt die Pflanze zu wachsen – und auf der Wildsea, selbst losgelöst von den Eisenwurzeln, geht das schnell. Um zu wissen, wie lange eine Pflanze zum Wachsen braucht, musst du die eingebaute Wachstumsleiste der Pflanze prüfen, direkt links von ihrem Typ zu finden.\nSchlachtmelonen haben eine Wachstumsleiste mit 5 Kästchen, das heißt, du musst 5 Kästchen füllen, bevor aus den Samen eine ausgewachsene, erntereife Pflanze geworden ist."},
 {h:"Länge der Wachstumsleiste"},
 {a:"Diese Wachstumsleiste kann durch verschiedene Faktoren verlängert oder verkürzt werden. Sowohl Beet als auch Nährboden können dies beeinflussen, ebenso das Geschick des Agronauten (oder anderen Crewmitglieds), der sie aussät, und die Art der verwendeten Samen. Auch Umweltfaktoren können eine Rolle spielen, doch das bleibt dem Glühwürmchen und der Gruppe als Ganzem überlassen. Der Versuch, eine Pflanze mitten im Winter oder im völlig falschen Klima wachsen zu lassen, kann unmöglich sein, der Wachstumsleiste zusätzliche Kästchen hinzufügen, die gefüllt werden müssen, oder gar keine Wirkung haben. Das hängt ganz davon ab, welche Art von Gartenerfahrung die Crew sucht."},
 {h:"Pflanzen wachsen lassen"},
 {a:"Es gibt zwei Hauptkräfte, die Samen zu Pflanzen machen – Zeit und Aufmerksamkeit. Das sind nicht die einzigen Faktoren, die eine Wachstumsleiste markieren können, aber bei Weitem die häufigsten."},
 {c:"Zeit", x:"Ein unaufhaltsamer Marsch, aber in diesem Fall einer, der durchweg zuträglich ist. Immer wenn eine bedeutende Zeitspanne vergangen ist, wird bei allen Schiffsgarten-Pflanzen ein Kästchen auf ihrer Wachstumsleiste markiert.\nWas ist eine bedeutende Zeitspanne? Du könntest sie in Tagen messen, wenn du eine zusätzliche Ebene der Feinheit hinzufügen willst, doch wir versuchen, diese Art der Buchführung in der Wildsea zu vermeiden. Stattdessen empfehlen wir, jede Wachstumsleiste zu markieren …", l:["Wenn ein Schiff eine Reise abschließt","Wenn die Crew im Hafen genug Zeit verbringt, um ein oder zwei Montagen zu absolvieren"]},
 {c:"Aufmerksamkeit", x:"Während Pflanzen auf der Wildsea meist zäh genug sind, dass sie nur Zeit brauchen, um vollständig zu gedeihen, kann Aufmerksamkeit der Crew diesen Prozess erheblich beschleunigen. Ein Agronaut mag hier einen Vorteil haben, doch jedes Crewmitglied kann eine Gießkanne oder ein Messer zum Unkrautjäten greifen und beginnen, zusätzliche Kästchen zu markieren.\nAnders als vergehende Zeit markiert Aufmerksamkeit nicht alle Pflanzen auf einem Schiff. Stattdessen kann ein Crewmitglied eine Aufgabe nutzen, um die Wachstumsleiste jeder Pflanze innerhalb eines einzelnen Beets um eins zu markieren. Das steht für die allgemeinen Tätigkeiten des Gießens, Beschneidens und Jätens, die Pflanzen gesund halten.\nEin Einzelner kann auch eine Fertigkeit (meist Pflegen) nutzen, um einen Gartenwurf zu machen, der sich auf eine einzelne bestimmte Pflanze konzentriert, indem er eine Aufgabe nutzt und auf der Tabelle rechts würfelt. Mehr Risiko, aber auch die Möglichkeit grünerer Belohnungen."},
 {h:"Gartenwurf-Ergebnisse"},
 {c:"6 · Triumph", x:"Markiere zwei Kästchen auf der Wachstumsleiste einer einzelnen Pflanze."},
 {c:"5–4 · Konflikt", x:"Markiere ein Kästchen auf der Wachstumsleiste einer einzelnen Pflanze."},
 {c:"3–1 · Desaster", x:"Leere eine Markierung auf der Wachstumsleiste einer einzelnen Pflanze."},
 {c:"Pasch · Wendung", x:"Füge der Pflanze, an der du arbeitest, einen Marker hinzu, bestimmt von einem anderen Crewmitglied oder dem Glühwürmchen (dieser Marker kann positiv oder negativ sein und könnte damit zusammenhängen, wie die Pflanze gepflegt wurde)."},
 {bsp:"Pflanzen wachsen lassen im Spiel", z:[
  ["Vic","Okay! Also … Was sind meine Optionen? Ich bin hier ein begeisterter Amateur, helft mir!"],
  ["Glühwürmchen","Ha, okay. Du kannst eine Aufgabe nutzen, um jeder Pflanze im Beet ein Kästchen hinzuzufügen – im Moment sind das nur die Ictorangen, und du müsstest nicht würfeln. Aber du kannst dich auch auf eine einzelne Pflanze konzentrieren und, wenn du magst, einen Gartenwurf machen. Die Fertigkeit Pflegen wäre da wirklich nützlich."],
  ["Vic","Ich habe einen Rang in Pflegen. Ich versuche es – kann ich einen Vorteil durch meine Ressource Wasserschlauch bekommen?"],
  ["Glühwürmchen","Auf jeden Fall, aber wenn du den Wurf vermasselst …"],
  ["Vic","Ich riskiere den Wasserschlauch, kein Problem. Das ist … Verdammt ja, eine 4, eine 4 und eine 5! Konflikt mit Wendung. Ein Kästchen auf der Wachstumsleiste markiert!"],
  ["Temba","Und die Wendung fügt einen neuen Marker hinzu, oder? Kann ich den bestimmen? Vielleicht macht das frühe Gießen die wachsenden Orangen Lebhaft, oder so? Richtig farbenfroh?"],
  ["Glühwürmchen","… Und nachdem der letzte der Piraten erledigt und ihre Bestien in die Freiheit entlassen sind, ist der Weg frei nach Jawsburg!"],
  ["Vic","Und dieses Fest auch. Ich habe meinen Sonnenhut bereit, und meine Blitzableiter auch."],
  ["Temba","Was wurde bei diesem Fest noch mal gefeiert?"],
  ["Inge","Warte! Wenn wir in den Hafen einlaufen, ist das das Ende unserer Reise, oder? Das ist ein ziemlich großer Moment für den Schiffsgarten!"],
  ["Glühwürmchen","Richtig, ist es! Weil eure Ictorangen – Verzeihung, eure Lebhaften Ictorangen – um einen Eisenschössling wachsen, markiert das Beenden einer Reise zwei Kästchen auf ihrer Wachstumsleiste."],
  ["Vic","Drei geschafft, eins noch … Und wir sind mindestens eine Woche im Hafen, vielleicht sind sie also erntereif, wenn wir fertig sind?"]
 ]},
 {h:"Pflanzen ernten"},
 {a:"Ist die Wachstumsleiste einer Pflanze voll, ist es Zeit für die Ernte, den Vorgang, eine Pflanze von Früchten und anderen nützlichen Teilen zu befreien, die entweder als Ressourcen (meist Proben, die die Crew nutzt) oder als Fracht (ein ausgezeichneter Weg, Einsätze zum weiteren Ausbau eines Schiffs zu gewinnen, wenn man sie im Hafen eintauscht) gewonnen werden können. Der erntende Charakter sollte entscheiden, welche Art von Probe ihn am meisten interessiert, vielleicht mit Hilfe des Glühwürmchens.\nErnten kann eine knifflige Angelegenheit sein, denn es geht seltener bloß darum, Früchte von einem großzügigen Ast zu pflücken, als darum, einen Garten nach den besten Exemplaren zu durchsuchen, während man sich mit Insekten, Dornen und peitschenden Ranken herumschlägt. Manche Ernten laufen einfach … nicht gut. Ist die Wachstumsleiste einer Pflanze voll, kann ein Crewmitglied eine Aufgabe nutzen, um auf der Tabelle rechts zu würfeln. Passt es zum Ton deines Spiels, kann man auch ganz auf einen Ernte-Wurf verzichten, indem man an Deck als Handlung eine einzelne reife Frucht pflückt und dann eine Wachstumsleiste zurücksetzt."},
 {c:"Nachwachsen oder neu säen?", x:"Eine Ernte setzt die Wachstumsleiste einer Pflanze meist zurück, aber du musst keine neuen Samen säen. Die Pflanze wächst immer wieder, sodass du sie im Lauf der Zeit wieder und wieder auf Proben, Fracht und Samen ernten kannst.\nDoch das heißt nicht, dass du nicht von vorn beginnen kannst, wenn du willst. Jederzeit kannst du eine Aufgabe nutzen, um eine Pflanze mit den Wurzeln auszureißen, die Viertel, die sie belegte, zu leeren und dir so zu erlauben, etwas Neues zu versuchen."},
 {h:"Ernte-Ergebnisse (Beet)"},
 {c:"6 · Triumph", x:"Du erhältst entweder …", l:["Eine Probe, die auf einer beliebigen ausgewachsenen Pflanze im Beet beruht, und einen Satz Samen dieser Pflanze. Setze die Wachstumsleiste dieser Pflanze zurück.","Ein Frachtstück, das auf einer beliebigen ausgewachsenen Pflanze im Beet beruht. Setze die Wachstumsleiste dieser Pflanze zurück."]},
 {c:"5–4 · Konflikt", x:"Du erhältst entweder …", l:["Eine Probe, die auf einer beliebigen ausgewachsenen Pflanze im Beet beruht. Setze die Wachstumsleiste dieser Pflanze zurück.","Einen Satz Samen von einer beliebigen ausgewachsenen Pflanze in diesem Beet. Setze die Wachstumsleiste dieser Pflanze zurück."]},
 {c:"3–1 · Desaster", x:"Du verdirbst die Pflanze, die du zu ernten versuchst, und erhältst keine Ressourcen. Setze die Wachstumsleiste dieser Pflanze zurück."},
 {c:"Pasch · Wendung", x:"Die Probe, die Samen oder die Fracht, die du erhältst, erhält einen positiven Marker, geliefert von dir oder einem anderen Spieler am Tisch. Bei einem Desaster erhältst du weiterhin nichts, setzt aber die Wachstumsleiste der Pflanze nicht zurück."},
 {bsp:"Ernten im Spiel", z:[
  ["Glühwürmchen","Nachdem das Fest vorbei ist, macht ihr euch auf den Rückweg zum Schiff. Schon bevor ihr an Bord seid, riecht ihr etwas Neues, saure Zitrusfrüchte."],
  ["Temba","Unsere Ictorangen! Hat die Festwoche ihnen genug Zeit zum Reifen gegeben?"],
  ["Glühwürmchen","Das hat sie. Cluster hängen von den Ästen des Eisenschösslings herab, schimmernd in zahlreichen Orange- und Goldtönen. Du kannst eine Aufgabe nutzen, um sie zu ernten, wenn du magst."],
  ["Inge","Gleich dabei! Das ist … eine 2, eine 3, eine 5 und eine 6!"],
  ["Glühwürmchen","Mit einem Triumph kannst du entweder ein Frachtstück oder eine Fruchtprobe und eine Samenprobe wählen. Leere die Wachstumsleiste in beiden Fällen."],
  ["Vic","Wenn wir uns für Fracht entscheiden, können wir die im Hafen als Einsatz nutzen, oder, um mehr Zeug für das Schiff zu kaufen?"],
  ["Temba","Oder um den Garten ein bisschen zu erweitern! Ich will einfach irgendwie ein eigenes Beet. Ich habe große Pläne …"],
  ["Inge","Dann also Fracht! Eine Kiste … Lebhafter Medizinischer Ictorangen! Mir fällt schon jemand in Roja Harbour ein, der die lieben wird …"]
 ]},
 {box:"Fäulnis, Wracks & Rückeroberung [Optionale Regeln]", x:["Das Regelwerk der Schiffsgärten ist ein ziemlich gehaltvolles, das viele Optionen bietet, einen zusätzlichen Bogen zum Verwalten und zusätzliche Tabellen, auf denen für bestimmte Tätigkeiten gewürfelt wird. Das ist Absicht – der Anbau eines Schiffsgartens soll sich wie ein Minispiel anfühlen, auf das sich die Crew nach Belieben einlassen kann. Wenn du ihn aber stärker in den Zeitfluss einer Geschichte einbinden und die Dringlichkeit erhöhen willst, sich mit Erzeugnissen zu befassen, während sie wachsen, kannst du Fäulnis als Faktor einbeziehen, indem du die folgende Sonderregel nutzt.",
  "Ist die Wachstumsleiste einer Pflanze vollständig markiert, beginne, für jede abgeschlossene Szene, in der die Proben ungeerntet bleiben, Kästchen auf der Leiste zu verbrennen. Wird die Pflanze geerntet, macht das Glühwürmchen einen zusätzlichen W6-Wurf. Ist das Ergebnis dieses Wurfs gleich der Zahl der verbrannten Kästchen auf der Leiste einer Pflanze oder kleiner, erhalten alle ihr entnommenen Proben den Marker Verfault. Dieses Verbrennen wird zusammen mit allen Markierungen geleert, wenn die Ernte abgeschlossen ist; es bleibt nicht bestehen, wie Verbrennen es sonst tut.",
  "Du kannst aber auch mehr Flexibilität ins Spiel bringen – ein Schiffsgarten-Beet ist schließlich ein Anziehungspunkt wie jeder andere in der Welt. Materialien können daraus gewonnen werden, wenn es beschädigt ist oder wenn eine Pflanze durch äußere Gefahren ruiniert wird. Nach einem Rüsselkäferbefall bekommst du vielleicht keine schön geformte Schlachtmelone, aber vielleicht kannst du trotzdem Käferschalen, abgeworfene Stacheln, Melonenhülsen, verdorbene Erde sammeln … Was auch immer für die verwendeten Beete und Nährböden sinnvoll ist."]}
]});

(function(){
 function I(n, k, cat, x, l){ var c = {c:n + " · " + SG.E(k) + " · " + cat}; if(x) c.x = x; if(l) c.l = l; return c; }
 L.push({id:"sg-schiff-anpassen", k:K, t:"Das Schiff anpassen", p:14, q:Q, b:[
 {a:"Es gibt jene, die sich über das Konzept eines Schiffsgartens lustig machen, eines mit denselben Früchten und Gewürzen beladenen Decks, die man auch wild in den Wellen findet. Warum, so fragen solche landgebundenen Leute, sich all die Mühe machen, diese Dinge selbst anzubauen, wenn man sie im Vorbeifahren direkt vom Ast pflücken kann?\n… Und in der Tat, warum? Warum sollte man außerdem eine Schattenquelle besuchen, wenn man im Regen stehen kann, oder sich einen Jagserry schnitzen, wenn ein geborgenes Rohr dasselbe leistet? Warum sich mit einem Antrieb abgeben für ein Schiff, das sich mühsam mit Haken an Stangen von Ort zu Ort schieben ließe – das würde für die Fortbewegung doch sicher genügen? Köpfe werden geschüttelt, wissende Blicke ausgetauscht, und Ernten und Aussaat gehen weiter."},
 {h:"Schiffsbasierte Optionen"},
 {a:"Wildsegler, die vom Gartenfieber gepackt werden, verbringen oft viel Zeit und noch mehr Einsätze damit, ihr Handwerk zu vervollkommnen. Während ein Großteil dieser Zeit, Mühe und Ressourcen in die Pflege der Gärten selbst fließt, gehen die Hingebungsvollsten noch einen Schritt weiter und fügen ihren Schiffen mehr als nur Beete hinzu. Diese Seite listet einige Optionen für ergebene Garten-Crews auf, von Ergänzungen bis zu Räumen, die mit Einsätzen gekauft werden können. Die durchschnittliche Werkstatt oder das Trockendock hätte keine Ahnung, wie man diese installiert, doch eine Bauerngemeinschaft könnte es selbstverständlich.\nDiese Optionen haben ihre Kategorie rechts neben ihren Einsatzkosten aufgeführt."},
 I("Hülsenschuppe",2,"Rumpf","Ein flexibles, organisches Rumpfmaterial aus alchemistisch veränderten Früchten und Pilzen.",["Dichtung +1","Schäden an der Panzerung und den Dichtungen des Schiffs lassen sich mit im Garten gezogenen Proben statt mit dem üblichen Bergegut reparieren."]),
 I("Parasitenplanken",3,"Rumpf","Holz, sorgfältig aus lange genutzten Ästen von Parasitenfarmen geschnitten, behandelt, um eintreffendem Schaden zu widerstehen, aber natürlich genug, dass Pflanzen dennoch Wurzeln schlagen können.",["Panzerung +1","Erhalte zwei Beete auf deinem Schiff mit dem Namen „Plankenwurzelbetten“. Parasit-Samen, die in diesen Beeten ausgesät werden, erhalten nicht das übliche zusätzliche Kästchen auf ihrer Wachstumsleiste."]),
 I("Dreschmaschine",2,"Biss","Rotierende Klingen am Bug des Schiffs, mit Netzen und Sammelausrüstung dahinter.",["Sägen +1","Wann immer du einen Pfad schlägst, würfle einen W6. Bei einer 6 erhältst du eine Wild- oder Wuchernd-Samenprobe, passend zu den Wellen, durch die du fährst."]),
 I("Pressrohre",1,"Antrieb","Kaum der stärkste Antrieb, den es gibt, aber einer, der für eine fleißige Crew äußerst leicht zu befeuern ist.",["Neigung +1","Tempo +1","Sägen −1","Befeuert mit Fruchtschalen und Gemüsehäuten."]),
 I("Bewässerungsanlage",1,"Zusatz","Aufmerksame könnten meinen, dies sei kaum mehr als eine Reihe zusammengewürfelter Eimer und Rohre mit Blattgummi-Dichtungen. Und sie hätten recht.",["Trockene Bedingungen wirken sich nicht negativ auf das Pflanzenwachstum im Schiffsgarten aus (es sei denn, sie halten mehrere Reisen in Folge ohne Zugang zu Wasser an)."]),
 I("Windfahnen-Rabir",2,"Zusatz","Maßgeschneidert, um sich mit den Winden zu drehen, und erzeugt ein musikalisches Summen, das alle bis auf die ungewöhnlichsten Gartenschädlinge fernhält.",["Alle Pflanzen in deinen Beeten sind resistent gegen Insektenfraß und insektenübertragene Krankheiten."]),
 I("Deckschuppen",1,"Raum","Noch vollgestopfter als die durchschnittliche Werkstatt; Schuppen sind mit einer Vielzahl einfacher Werkzeuge für Wartung und Vorbereitung von Schiffsgarten-Beeten ausgestattet."),
 I("Interne Saatbank",2,"Raum","Ein Raum, der nicht nur der sicheren Lagerung von Samen dient, sondern auch dazu, sie mit schmerzhaft langsamen, aber verlässlichen Methoden, die von Generationen von Parasitenbauern genutzt wurden, von Crezzerin-Verunreinigung zu befreien.",["Wähle zu Beginn einer Reise einen einzelnen Satz Samen mit dem Marker Wild oder Wuchernd. Am Ende der Reise verlieren diese Samen ihren ursprünglichen Marker und erhalten stattdessen den Marker Parasit."]),
 I("Crezzerkanone",2,"Bewaffnung","Versuchst du, Dinge auf die altmodische Art anzubauen? Dann kannst du genauso gut etwas aus all dem überschüssigen Crezzerin machen …",["Verursacht massiven FK-Gift-Schaden"]),
 {c:"Heulende Vogelscheuche · 3er-Leiste · 2 Einsätze · Offizier", x:"Es ist erstaunlich, was man mit alten Kleidern, einem Stock und etwas Füllung anstellen kann. Und erschreckend, was man erreicht, wenn man ein hungriges Flüstern dazumischt.", l:["Alle deine Beete sind resistent gegen Fraß durch Bestien."]},
 {c:"Grünfinger · 3er-Leiste · 2 Einsätze · Bande", x:"Lehrlings-Agronauten, die ihre ersten Schritte auf dem Weg des schiffsgebundenen Ackerbaus tun. Für fortgeschrittenere Methoden sind sie noch nicht bereit, aber im Pflanzen sind sie geschickt.", l:["Das Hinzufügen von Samen zu einem Schiffsgarten-Beet kostet keine Aufgabe."]},
 {c:"Goldene Marienkäfer · 3er-Leiste · 2 Einsätze · Rudel", x:"Viele Jahre des Ausprobierens haben diesen hungrigen Kleinen beigebracht, vor allem frisch gewachsenes Unkraut ins Visier zu nehmen.", l:["Alle deine Beete sind resistent gegen Unkraut."]},
 {c:"Kleptothermische Dromaten · 3er-Leiste · 2 Einsätze · Rudel", x:"Eine Horde daumengroßer Fledermäuse mit unglaublicher Kontrolle über ihre eigene Körpertemperatur und der Fähigkeit, Wasser zu speichern und abzugeben, um ihre Umgebung für ihre Jungen angemessen stabil zu halten. Darauf trainiert, in Beeten zu nisten.", l:["Alle deine Beete sind resistent gegen Wettergefahren."]}
 ]});
})();

L.push({id:"sg-wildnis", k:K, t:"Schiffsgärten & die Wildnis", p:15, q:Q, b:[
 {a:"Wenn du die Schiffsgarten-Erweiterung nutzt, sind die rauschenden Wellen sowohl nützlicher als auch weniger nützlich als in einem typischen Spiel. Nützlicher, weil sie eine brauchbare Quelle für Samen und bestimmte Nährböden sind. Weniger nützlich, weil die Einführung des Markers Wild für Erzeugnisse, die direkt von den Wellen (und aus Samen von auf den Wellen gewachsenen Pflanzen) stammen, natürlich gefundene Proben wegen ihres Crezzerin-Gehalts gefährlich macht. Mehr Einzelheiten zu wichtigen Schiffsgarten-Markern findest du auf S. 10.\nJe nach dem Ton des Spiels, das du möchtest, und der Bedeutung, die dein Schiffsgarten für die Ernährung deiner Crew haben soll, kannst du gern eine der folgenden Konventionen nutzen …"},
 {c:"Die Welt ist ein Garten", x:"Alle Erzeugnisse, die den Wellen entnommen werden, folgen denselben Regeln wie in einem Schiffsgarten gezogene Proben. Der Verzehr wildgewachsener Proben verursacht Gift-Schaden, es sei denn, ein Charakter hat Resistenz gegen Crezzerin oder Gift, oder er verzehrt sie in einer gekochten Mahlzeit."},
 {c:"Natürliche Auslese", x:"Proben, die in einem Schiffsgarten entstehen, folgen allen in dieser Erweiterung aufgeführten Regeln, doch ausgewachsenes Essbares von den Wellen kommt ohne besonderen Marker. Es wird angenommen, dass Charaktere nur die am wenigsten von Crezzerin durchsetzten Ressourcen aus der Fülle nehmen, die die See bietet."},
 {c:"Frei zum Schlemmen", x:"Das Leben auf den Wellen hat Wildsegler gegen geringe Mengen aufgenommenen Crezzerins abgehärtet, selbst wenn sie keine allgemeine Crezzerin-Resistenz haben. Proben mit dem Marker Wild, ob von den Wellen oder aus einem Schiffsgarten, sind für Crew und Unterbesatzung ohne jeden Schaden verzehrbar."}
]});

function SG_P(id){ return SG.pflanze(SG.byId(id)); }
})(WS_NACH.schiffe);
